"use client"

import * as React from "react"
import { PieChartIcon } from "lucide-react"
import { Label, Pie, PieChart } from "recharts"

import { SlidingNumber } from "@/components/motion-primitives/sliding-number"
import { EmptyState } from "@/components/empty-state"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"
import type { StatusSlice } from "@/features/attendance/dashboard"

const chartConfig = {
  count: { label: "Students" },
  present: { label: "Present", color: "var(--chart-2)" },
  late: { label: "Late", color: "var(--chart-4)" },
  absent: { label: "Absent", color: "var(--destructive)" },
  norecord: { label: "No tap recorded yet", color: "var(--muted-foreground)" },
} satisfies ChartConfig

export function AttendanceDistributionChart({
  distribution,
  attendanceRate,
}: {
  distribution: StatusSlice[]
  attendanceRate: number
}) {
  const slices = React.useMemo(
    () =>
      distribution.map((slice) => {
        const key = slice.status.toLowerCase()

        return {
          key,
          status: slice.status,
          count: slice.count,
          fill: `var(--color-${key})`,
        }
      }),
    [distribution]
  )

  const total = slices.reduce((sum, slice) => sum + slice.count, 0)

  return (
    <Card className="flex flex-col">
      <CardHeader>
        <CardTitle>Attendance Status Distribution</CardTitle>
        <CardDescription>Recorded statuses and students with no tap yet today</CardDescription>
      </CardHeader>
      <CardContent className="flex-1">
        {total > 0 ? (
          <ChartContainer
            config={chartConfig}
            role="img"
            aria-label="Attendance status distribution for today"
            className="mx-auto aspect-square h-64"
          >
            <PieChart>
              <ChartTooltip
                cursor={false}
                content={<ChartTooltipContent nameKey="key" hideLabel />}
              />
              <Pie
                data={slices}
                dataKey="count"
                nameKey="key"
                innerRadius={62}
                strokeWidth={4}
              >
                <Label
                  content={({ viewBox }) => {
                    if (
                      !viewBox ||
                      !("cx" in viewBox) ||
                      viewBox.cx == null ||
                      viewBox.cy == null
                    )
                      return null
                    const cx = viewBox.cx
                    const cy = viewBox.cy

                    return (
                      <foreignObject
                        x={cx - 70}
                        y={cy - 50}
                        width={140}
                        height={68}
                      >
                        <div className="flex h-full w-full flex-col items-center justify-center gap-0.5">
                          <SlidingNumber
                            value={attendanceRate}
                            decimalPlaces={1}
                            suffix="%"
                            className="text-2xl font-semibold text-foreground"
                          />
                          <span className="text-xs text-muted-foreground">
                            <SlidingNumber value={total} /> students
                          </span>
                        </div>
                      </foreignObject>
                    )
                  }}
                />
              </Pie>
              <ChartLegend content={<ChartLegendContent nameKey="key" className="flex-wrap gap-y-2" />} />
            </PieChart>
          </ChartContainer>
        ) : (
          <EmptyState
            icon={PieChartIcon}
            title="No students to chart"
            description="Add active students to see today's attendance statuses."
          />
        )}
      </CardContent>
    </Card>
  )
}
